<?php use App\Core\CSRF;$labels=['waiting'=>'Aguardando','offered'=>'Oferta enviada','converted'=>'Convertida','expired'=>'Expirada','cancelled'=>'Cancelada']; ?>
<div class="sports-head"><div><span class="sports-kicker">OCUPAÇÃO</span><h1>Lista de espera da Arena</h1><p>Pedidos por quadra, modalidade, data e faixa de horário, sem profissional envolvido.</p></div></div>
<div class="card border-0 shadow-sm"><div class="card-body"><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Cliente</th><th>Quadra/Modalidade</th><th>Data</th><th>Preferência</th><th>Status</th><th>Ação</th></tr></thead><tbody><?php foreach($entries as $e):?><tr><td><strong><?=htmlspecialchars($e['customer_name'])?></strong><br><small><?=htmlspecialchars($e['customer_phone'])?></small></td><td><?=htmlspecialchars($e['court_name']??'Qualquer quadra')?><br><small><?=htmlspecialchars($e['modality_name']??'Qualquer modalidade')?></small></td><td><?=date('d/m/Y',strtotime($e['preferred_date']))?></td><td><?=$e['preferred_start']?substr($e['preferred_start'],0,5):'Flexível'?><?php if($e['preferred_end']):?>–<?=substr($e['preferred_end'],0,5)?><?php endif;?></td><td><?=htmlspecialchars($labels[$e['status']]??$e['status'])?></td><td><form method="post" action="/sports/waitlist/<?=(int)$e['id']?>/status" class="d-flex gap-1"><?=CSRF::field()?><select class="form-select form-select-sm" name="status"><?php foreach($labels as $k=>$v):?><option value="<?=$k?>" <?=$e['status']===$k?'selected':''?>><?=$v?></option><?php endforeach;?></select><button class="btn btn-sm btn-outline-primary">Salvar</button></form></td></tr><?php endforeach;?><?php if(!$entries):?><tr><td colspan="6" class="text-secondary">Nenhum cliente aguardando horário.</td></tr><?php endif;?></tbody></table></div></div></div>
